<?php
require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Database.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../core/JalaliDate.php';require_once __DIR__.'/../lib/OrgAccess.php';require_once __DIR__.'/../services/WorkPlannerService.php';
Auth::requireLogin();$pageTitle='پلنر کاری نقش‌محور';$actor=Auth::user();$actorId=(int)$actor['id'];$canAssign=Auth::isAdmin()||Auth::can('work_planner.assign')||Auth::can('work_planner.manage');$allowedIds=OrgAccess::accessibleUserIds($actor);if(!$allowedIds)$allowedIds=[$actorId];
function planner_targets(string $scope,array $post,array $allowed): array{$params=[];$sql='SELECT id FROM users WHERE status="active"';if($scope==='user'){$sql.=' AND id=?';$params[]=(int)($post['scope_value']??0);}elseif($scope==='unit'){$sql.=' AND org_unit_id=?';$params[]=(int)($post['scope_value']??0);}elseif($scope==='role'){$sql.=' AND org_role_id=?';$params[]=(int)($post['scope_value']??0);}elseif(in_array($scope,['supervisor_team','manager_team'],true)){$manager=(int)($post['scope_value']??0);$context=OrgAccess::userContext($manager);return $context?array_values(array_intersect(array_diff(OrgAccess::accessibleUserIds($context),[$manager]),$allowed)):[];}else return [];return array_values(array_intersect(array_map('intval',array_column(Database::fetchAll($sql,$params),'id')),$allowed));}
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Auth::verifyCsrf($_POST['csrf_token']??'')){flash('درخواست نامعتبر است.','danger');redirect('/admin/work-planner.php');}$action=(string)($_POST['action']??'');try{
 if($action==='create'){if(!$canAssign)throw new InvalidArgumentException('برای تخصیص وظیفه دسترسی ندارید.');$title=trim((string)($_POST['title']??''));$scope=in_array($_POST['scope']??'',['user','unit','role','supervisor_team','manager_team'],true)?$_POST['scope']:'user';$targets=planner_targets($scope,$_POST,$allowedIds);$start=JalaliDate::toGregorian($_POST['start_date']??'')?:date('Y-m-d');$due=JalaliDate::toGregorian($_POST['due_date']??'')?:$start;if($title===''||!$targets)throw new InvalidArgumentException('عنوان و حداقل یک کاربر مجاز الزامی است.');$created=0;foreach($targets as $target){$ctx=OrgAccess::userContext($target);Database::execute('INSERT INTO work_planner_tasks(user_id,employee_id,assigned_by,assigned_to_role_id,assigned_to_unit_id,title,description,task_type,priority,status,start_date,due_date,progress_percent,related_module,related_record_id,is_locked,is_personal,is_visible_on_dashboard,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,"todo",?,?,0,?,?,?,0,?,NOW(),NOW())',[$target,$target,$actorId,$ctx['org_role_id']??null,$ctx['org_unit_id']??null,$title,trim((string)($_POST['description']??'')),in_array($_POST['task_type']??'',['daily','weekly','monthly','periodic','kpi_related','report','meeting','follow_up','field_visit','admin_task','custom'],true)?$_POST['task_type']:'custom',in_array($_POST['priority']??'',['low','normal','high','urgent'],true)?$_POST['priority']:'normal',$start,$due,trim((string)($_POST['related_module']??'')),(int)($_POST['related_record_id']??0)?:null,isset($_POST['is_locked'])?1:0,isset($_POST['dashboard'])?1:0]);$taskId=(int)Database::lastInsertId();WorkPlannerService::logTaskAction($taskId,$actorId,'assigned',null,['user_id'=>$target,'scope'=>$scope]);$created++;}flash($created.' وظیفه با موفقیت تخصیص داده شد.');
 }elseif($action==='status'){if(!WorkPlannerService::updateTaskStatus((int)$_POST['task_id'],(string)$_POST['status'],$actorId))throw new InvalidArgumentException('تغییر وضعیت این وظیفه مجاز نیست.');flash('وضعیت وظیفه بروزرسانی شد.');
 }elseif($action==='progress'){if(!WorkPlannerService::updateTaskProgress((int)$_POST['task_id'],(int)$_POST['progress_percent'],$actorId))throw new InvalidArgumentException('ثبت پیشرفت این وظیفه مجاز نیست.');flash('درصد پیشرفت ثبت شد.');
 }elseif($action==='comment'){$taskId=(int)$_POST['task_id'];$text=trim((string)($_POST['comment_text']??''));if($text===''||!WorkPlannerService::canUserAccessTask($actorId,$taskId))throw new InvalidArgumentException('متن پیگیری یا دسترسی وظیفه معتبر نیست.');Database::execute('INSERT INTO work_planner_comments(task_id,user_id,comment_text,created_at,updated_at) VALUES (?,?,?,NOW(),NOW())',[$taskId,$actorId,$text]);WorkPlannerService::logTaskAction($taskId,$actorId,'comment_added',null,null,$text);flash('پیگیری ثبت شد.');
 }elseif($action==='generate'){if(!$canAssign)throw new InvalidArgumentException('برای تولید وظایف دسترسی ندارید.');$count=0;foreach($allowedIds as $id)$count+=WorkPlannerService::generateDailyTasksForUser((int)$id);flash($count.' وظیفه دوره‌ای جدید ساخته شد.');}
}catch(InvalidArgumentException $e){flash($e->getMessage(),'danger');}catch(Throwable $e){error_log('Work planner admin: '.$e->getMessage());flash('عملیات پلنر انجام نشد. لطفاً دوباره تلاش کنید.','danger');}redirect('/admin/work-planner.php');}
$ph=implode(',',array_fill(0,count($allowedIds),'?'));$where=["t.user_id IN ({$ph})"];$params=$allowedIds;foreach(['user_id'=>'t.user_id','unit_id'=>'u.org_unit_id','role_id'=>'u.org_role_id'] as $key=>$column){$v=(int)($_GET[$key]??0);if($v){$where[]="$column=?";$params[]=$v;}}foreach(['status'=>'t.status','priority'=>'t.priority'] as $key=>$column){$v=trim((string)($_GET[$key]??''));if($v!==''){$where[]="$column=?";$params[]=$v;}}if($from=JalaliDate::toGregorian($_GET['from_date']??'')){$where[]='t.due_date>=?';$params[]=$from;}if($to=JalaliDate::toGregorian($_GET['to_date']??'')){$where[]='t.due_date<=?';$params[]=$to;}
$tasks=Database::fetchAll('SELECT t.*,u.name user_name,ou.title unit_title,r.title role_title,a.name assigner_name,o.title okr_title FROM work_planner_tasks t LEFT JOIN users u ON u.id=t.user_id LEFT JOIN org_units ou ON ou.id=u.org_unit_id LEFT JOIN org_roles r ON r.id=u.org_role_id LEFT JOIN users a ON a.id=t.assigned_by LEFT JOIN okr_objectives o ON t.related_module="okr" AND o.id=t.related_record_id WHERE '.implode(' AND ',$where).' ORDER BY CASE WHEN t.due_date<CURDATE() AND t.status NOT IN("done","cancelled") THEN 0 WHEN t.priority="urgent" THEN 1 WHEN t.status="in_progress" THEN 2 ELSE 3 END,t.due_date,t.id DESC',$params);
if(($_GET['export']??'')==='csv'){header('Content-Type:text/csv;charset=utf-8');header('Content-Disposition:attachment;filename="work-planner.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['کاربر','واحد','نقش','وظیفه','اولویت','وضعیت','پیشرفت','مهلت']);foreach($tasks as $t)fputcsv($out,[$t['user_name'],$t['unit_title'],$t['role_title'],$t['title'],$t['priority'],$t['status'],$t['progress_percent'],$t['due_date']]);fclose($out);exit;}
$users=Database::fetchAll("SELECT id,name FROM users WHERE status='active' AND id IN ({$ph}) ORDER BY name",$allowedIds);$units=Database::fetchAll('SELECT id,title FROM org_units WHERE active=1 ORDER BY sort_order,title');$roles=Database::fetchAll('SELECT id,title FROM org_roles WHERE active=1 ORDER BY sort_order,title');require __DIR__.'/../views/partials/admin-header.php';?>
<div class="section-heading-row"><div><h1>پلنر کاری نقش‌محور</h1><p class="muted">وظایف شخصی و تیمی با اولویت‌بندی، پیگیری و اتصال به ماژول‌های سازمانی</p></div><?php if($canAssign):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="action" value="generate"><button class="btn">تولید وظایف امروز</button></form><?php endif?></div>
<?php if($canAssign):?><section class="card admin-form"><h2>ایجاد و تخصیص وظیفه</h2><form method="post" id="plannerAssign"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="action" value="create"><div class="grid grid-3"><label class="form-field"><span>عنوان</span><input name="title" required></label><label class="form-field"><span>دامنه</span><select name="scope" id="plannerScope"><option value="user">کاربر</option><option value="unit">واحد</option><option value="role">نقش</option><option value="supervisor_team">تیم سرپرست</option><option value="manager_team">تیم مدیر</option></select></label><label class="form-field" data-planner-scope="user"><span>کاربر</span><select data-scope-value><?php foreach($users as $item):?><option value="<?=e((string)$item['id'])?>"><?=e($item['name'])?></option><?php endforeach?></select></label><label class="form-field" data-planner-scope="unit" hidden><span>واحد</span><select data-scope-value><?php foreach($units as $item):?><option value="<?=e((string)$item['id'])?>"><?=e($item['title'])?></option><?php endforeach?></select></label><label class="form-field" data-planner-scope="role" hidden><span>نقش</span><select data-scope-value><?php foreach($roles as $item):?><option value="<?=e((string)$item['id'])?>"><?=e($item['title'])?></option><?php endforeach?></select></label><label class="form-field" data-planner-scope="supervisor_team manager_team" hidden><span>مدیر یا سرپرست</span><select data-scope-value><?php foreach($users as $item):?><option value="<?=e((string)$item['id'])?>"><?=e($item['name'])?></option><?php endforeach?></select></label><label class="form-field"><span>نوع</span><select name="task_type"><option value="custom">سفارشی</option><option value="daily">روزانه</option><option value="report">گزارش</option><option value="meeting">جلسه</option><option value="follow_up">پیگیری</option><option value="field_visit">ویزیت میدانی</option><option value="kpi_related">مرتبط با KPI</option></select></label><label class="form-field"><span>اولویت</span><select name="priority"><option value="normal">عادی</option><option value="high">بالا</option><option value="urgent">فوری</option><option value="low">کم</option></select></label><label class="form-field"><span>شروع</span><input class="jalali-date-input" name="start_date"></label><label class="form-field"><span>مهلت</span><input class="jalali-date-input" name="due_date"></label><label class="form-field"><span>ماژول مرتبط</span><input name="related_module"></label><label class="form-field"><span>شناسه مرتبط</span><input type="number" min="1" name="related_record_id"></label><label class="checkbox-item"><input type="checkbox" name="is_locked"> وظیفه اجباری/قفل‌شده</label><label class="checkbox-item"><input type="checkbox" name="dashboard" checked> نمایش در داشبورد</label><label class="form-field grid-span-2"><span>شرح</span><textarea name="description"></textarea></label></div><button class="btn btn-primary">ثبت وظیفه</button></form></section><?php endif?>
<form class="card admin-form" method="get"><h2>فیلتر وظایف</h2><div class="grid grid-3"><label class="form-field"><span>کاربر</span><select name="user_id"><option value="">همه</option><?php foreach($users as $item):?><option value="<?=e((string)$item['id'])?>" <?=(int)($_GET['user_id']??0)===(int)$item['id']?'selected':''?>><?=e($item['name'])?></option><?php endforeach?></select></label><label class="form-field"><span>وضعیت</span><select name="status"><option value="">همه</option><?php foreach(['todo'=>'انجام‌نشده','in_progress'=>'در حال انجام','waiting'=>'منتظر','blocked'=>'مسدود','done'=>'تکمیل','cancelled'=>'لغو'] as $v=>$l):?><option value="<?=e($v)?>" <?=($_GET['status']??'')===$v?'selected':''?>><?=e($l)?></option><?php endforeach?></select></label><label class="form-field"><span>اولویت</span><select name="priority"><option value="">همه</option><?php foreach(['low'=>'کم','normal'=>'عادی','high'=>'بالا','urgent'=>'فوری'] as $v=>$l):?><option value="<?=e($v)?>" <?=($_GET['priority']??'')===$v?'selected':''?>><?=e($l)?></option><?php endforeach?></select></label><label class="form-field"><span>از مهلت</span><input class="jalali-date-input" name="from_date" value="<?=e($_GET['from_date']??'')?>"></label><label class="form-field"><span>تا مهلت</span><input class="jalali-date-input" name="to_date" value="<?=e($_GET['to_date']??'')?>"></label></div><div class="form-actions"><button class="btn btn-primary">اعمال</button><button class="btn" name="export" value="csv">خروجی CSV</button></div></form>
<section class="card"><div class="table-wrap"><table><thead><tr><th>کاربر</th><th>وظیفه</th><th>اولویت</th><th>وضعیت / پیشرفت</th><th>مهلت</th><th>پیگیری</th></tr></thead><tbody><?php foreach($tasks as $task):?><tr><td><?=e($task['user_name']?:'کاربر نامشخص')?><small><?=e(($task['unit_title']?:'-').' / '.($task['role_title']?:'-'))?></small></td><td><strong><?=e($task['title'])?></strong><small><?=e($task['description']?:'-')?></small><?php if(($task['related_module']??'')==='okr'&&!empty($task['okr_title'])):?><small><a href="/admin/okr-objective.php?id=<?=e((string)$task['related_record_id'])?>">مرتبط با OKR: <?=e($task['okr_title'])?></a></small><?php elseif($task['related_module']):?><small><?=e($task['related_module'].' #'.($task['related_record_id']?:'-'))?></small><?php endif?></td><td><span class="badge"><?=e($task['priority'])?></span></td><td><form method="post" class="row-actions"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="task_id" value="<?=e((string)$task['id'])?>"><select name="status"><?php foreach(['todo','in_progress','waiting','blocked','done','cancelled'] as $status):?><option value="<?=e($status)?>" <?=$task['status']===$status?'selected':''?>><?=e($status)?></option><?php endforeach?></select><button class="btn btn-small">ثبت</button></form><small><?=e((string)$task['progress_percent'])?>٪</small></td><td><?=e($task['due_date']?format_jalali_date($task['due_date']):'-')?></td><td><details><summary>پیشرفت و کامنت</summary><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="action" value="progress"><input type="hidden" name="task_id" value="<?=e((string)$task['id'])?>"><input type="number" min="0" max="100" name="progress_percent" value="<?=e((string)$task['progress_percent'])?>"><button class="btn btn-small">پیشرفت</button></form><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="action" value="comment"><input type="hidden" name="task_id" value="<?=e((string)$task['id'])?>"><textarea name="comment_text" required></textarea><button class="btn btn-small">ثبت پیگیری</button></form><a class="btn btn-small" href="?task_id=<?=e((string)$task['id'])?>#task-history">تاریخچه کامل</a></details></td></tr><?php endforeach?><?php if(!$tasks):?><tr><td colspan="6">وظیفه‌ای مطابق فیلترها ثبت نشده است.</td></tr><?php endif?></tbody></table></div></section>
<script>const ps=document.getElementById('plannerScope'),pf=document.getElementById('plannerAssign');function syncPlannerScope(){document.querySelectorAll('[data-planner-scope]').forEach(el=>el.hidden=!el.dataset.plannerScope.split(' ').includes(ps.value));}ps?.addEventListener('change',syncPlannerScope);syncPlannerScope();pf?.addEventListener('submit',()=>{const box=[...document.querySelectorAll('[data-planner-scope]')].find(el=>el.dataset.plannerScope.split(' ').includes(ps.value));const input=document.createElement('input');input.type='hidden';input.name='scope_value';input.value=box?.querySelector('[data-scope-value]')?.value||'';pf.append(input);});</script>
<?php $historyTaskId=(int)($_GET['task_id']??0);if($historyTaskId&&WorkPlannerService::canUserAccessTask($actorId,$historyTaskId)):$historyTask=Database::fetch('SELECT t.*,u.name user_name FROM work_planner_tasks t LEFT JOIN users u ON u.id=t.user_id WHERE t.id=?',[$historyTaskId]);$historyLogs=Database::fetchAll('SELECT l.*,u.name actor_name FROM work_planner_task_logs l LEFT JOIN users u ON u.id=l.user_id WHERE l.task_id=? ORDER BY l.id DESC',[$historyTaskId]);$historyComments=Database::fetchAll('SELECT c.*,u.name actor_name FROM work_planner_comments c LEFT JOIN users u ON u.id=c.user_id WHERE c.task_id=? ORDER BY c.id DESC',[$historyTaskId]);?>
<section class="card" id="task-history"><h2>تاریخچه <?=e($historyTask['title']??'وظیفه')?></h2><div class="grid grid-2"><div><h3>رویدادها</h3><?php foreach($historyLogs as $log):?><article class="planner-log"><strong><?=e($log['actor_name']?:'سیستم')?></strong><span><?=e(work_planner_status_label($log['action'])==='_never_'?'':$log['action'])?></span><small><?=e($log['created_at'])?></small><?php if($log['note']):?><p><?=e($log['note'])?></p><?php endif?></article><?php endforeach?><?php if(!$historyLogs):?><p class="muted">رویدادی ثبت نشده است.</p><?php endif?></div><div><h3>کامنت‌ها</h3><?php foreach($historyComments as $comment):?><article class="planner-log"><strong><?=e($comment['actor_name']?:'کاربر')?></strong><p><?=e($comment['comment_text'])?></p><small><?=e($comment['created_at'])?></small></article><?php endforeach?><?php if(!$historyComments):?><p class="muted">کامنتی ثبت نشده است.</p><?php endif?></div></div></section>
<?php endif;require __DIR__.'/../views/partials/admin-footer.php';?>
